import java.util.*;

class Stack<T> {
    private final List<T> items = new ArrayList<>();

    void push(T x) { items.add(x); }
    T pop() { return items.remove(items.size() - 1); }
    T peek() { return items.get(items.size() - 1); }
    boolean isEmpty() { return items.isEmpty(); }
    int size() { return items.size(); }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Stack<String> st = new Stack<>();
        for (int i = 0; i < n; i++) {
            String cmd = sc.next();
            switch (cmd) {
                case "push" -> st.push(sc.next());
                case "pop" -> System.out.println(st.isEmpty() ? "empty" : st.pop());
                case "peek" -> System.out.println(st.isEmpty() ? "empty" : st.peek());
                default -> System.out.println(st.size());
            }
        }
    }
}

