        Map<Character, List<String>> groups = new TreeMap<>();
        for (String w : unique) {
            groups.computeIfAbsent(w.charAt(0), k -> new ArrayList<>()).add(w);
        }
        System.out.println("Grouped: " + groups);

        Deque<String> stack = new ArrayDeque<>();
        for (String w : words) stack.push(w);
        System.out.println("Top of stack: " + stack.peek());

        PriorityQueue<String> byLength = new PriorityQueue<>(Comparator.comparing(String::length));
        byLength.addAll(words);
        System.out.println("Shortest: " + byLength.poll());
    }
