import java.util.*;
import java.util.stream.*;

record Sale(String region, String product, int amount) {}

public class Main {
    public static void main(String[] args) {
        List<Sale> sales = List.of(
            new Sale("North", "pen", 120), new Sale("South", "book", 300),
            new Sale("North", "book", 250), new Sale("East", "pen", 80),
            new Sale("South", "pen", 60));

        int total = sales.stream().mapToInt(Sale::amount).sum();
        System.out.println("Total: " + total);

        Map<String, Integer> byRegion = sales.stream()
            .collect(Collectors.groupingBy(Sale::region, TreeMap::new, Collectors.summingInt(Sale::amount)));
        System.out.println("By region: " + byRegion);

        List<String> bigSales = sales.stream()
            .filter(s -> s.amount() >= 100)
            .map(s -> s.product() + "@" + s.region())
            .toList();
        System.out.println("Big sales: " + bigSales);

        String best = sales.stream().max(Comparator.comparingInt(Sale::amount))
            .map(Sale::region).orElse("none");
        System.out.println("Best single sale region: " + best);
    }
}

