import java.util.*;
import java.util.stream.*;

record Sale(String region, int amount) {}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Sale> sales = new ArrayList<>();
        for (int i = 0; i < n; i++) sales.add(new Sale(sc.next(), sc.nextInt()));
        Map<String, Integer> totals = sales.stream()
            .collect(Collectors.groupingBy(Sale::region, TreeMap::new, Collectors.summingInt(Sale::amount)));
        totals.forEach((region, total) -> System.out.println(region + " " + total));
        String top = totals.entrySet().stream()
            .sorted(Map.Entry.<String, Integer>comparingByValue().reversed()
                    .thenComparing(Map.Entry.comparingByKey()))
            .map(Map.Entry::getKey)
            .findFirst().orElse("none");
        System.out.println("Top: " + top);
    }
}
